const operations = [];
let n = 0;
const id = (p) => `${p}-${++n}`;
const create = (shape) => operations.push({ type: 'create', shape: { id: id(shape.type), ...shape } });

const C = '#172033';
const MUTED = '#667085';
const GRID = '#d8dde6';
const BLUE = '#2563eb';
const RED = '#dc2626';
const GREEN = '#16a34a';
const AMBER = '#d97706';
const PURPLE = '#7c3aed';
const PANEL = '#f7f8fa';

function text(x,y,text,fontSize=16,color=C,w=300,h=24,weight=400) {
  create({type:'text',x,y,w,h,text,color,font:'sans',fontSize,fontWeight:weight});
}
function rect(x,y,w,h,color=C,fill=null) {
  create({type:'rectangle',x,y,w,h,color,fill});
}
function line(x,y,w,h,color=C,strokeWidth=2) {
  create({type:'line',x,y,w,h,color,strokeWidth});
}

// Overall title
text(50,36,'单位圆：30°、45°、60° 三角函数几何比较',30,C,900,42,700);
text(50,78,'横坐标 cosθ，纵坐标 sinθ；单位圆上的点为 (cosθ, sinθ)',16,MUTED,650,24,400);

// Main panels
rect(50,110,650,760,'#cbd3df','#ffffff');
rect(740,110,650,760,'#cbd3df','#ffffff');

text(72,128,'一、单位圆与几何表示',22,C,500,32,700);
text(762,128,'二、精确值与变化趋势',22,C,500,32,700);

// Unit circle geometry
const cx = 320, cy = 430, r = 200;
// axes and circle
line(95,cy,510,0,'#98a2b3',2);
line(cx,205,0,470,'#98a2b3',2);
create({type:'ellipse',x:cx-r,y:cy-r,w:r*2,h:r*2,color:'#172033',fill:null});

// axis endpoints and labels
text(cx+245,420,'x',18,C,30,24,700);
text(cx-10,205,'y',18,C,30,24,700);
text(cx+r-4,438,'1',14,MUTED,30,20,400);
text(cx-r-8,438,'−1',14,MUTED,40,20,400);
text(cx-12,438,'0',14,MUTED,30,20,400);
text(cx-12,cy-r-18,'1',14,MUTED,30,20,400);

// center
create({type:'ellipse',x:cx-4,y:cy-4,w:8,h:8,color:'#172033',fill:'#172033'});

// angles
const angles = [
  {deg:30,c:RED,a:Math.PI/6,dx:173.205,dy:-100},
  {deg:45,c:GREEN,a:Math.PI/4,dx:141.421,dy:-141.421},
  {deg:60,c:BLUE,a:Math.PI/3,dx:100,dy:-173.205},
];

// legend
text(76,165,'角度',14,MUTED,60,20,700);
for (const [i,a] of angles.entries()) {
  const y=190+i*28;
  line(76,y+8,24,0,a.c,4);
  text(108,y,a.deg+'°',14,a.c,70,20,700);
}

// tangent axis
const tx=cx+r;
line(tx,205,0,470,'#94a3b8',2);
text(tx+8,205,'正切轴 x = 1',15,PURPLE,130,24,700);

// Reference triangles and rays
for (const a of angles) {
  const px=cx+a.dx, py=cy+a.dy;
  // ray
  line(cx,cy,a.dx,a.dy,a.c,3);
  // projection triangle sides
  line(cx,py,a.dx,0,a.c,2);
  line(px,py,0,-a.dy,a.c,2);
  // right-angle marker
  rect(px-8,py+(a.dy < 0 ? 0 : -8),8,8,'#98a2b3', '#f8fafc');
  // terminal point
  create({type:'ellipse',x:px-5,y:py-5,w:10,h:10,color:a.c,fill:a.c});
}

// tangent segments
const tangents = [
  {deg:30,c:RED,h:-115.47,label:'tan30° = √3/3'},
  {deg:45,c:GREEN,h:-200,label:'tan45° = 1'},
  {deg:60,c:BLUE,h:-346.41,label:'tan60° = √3'},
];
for (const t of tangents) {
  line(tx,cy,0,t.h,t.c,4);
  create({type:'ellipse',x:tx-4,y:cy+t.h-4,w:8,h:8,color:t.c,fill:t.c});
}

// terminal labels (positioned to remain readable)
text(500,315,'30°',15,RED,55,22,700);
text(468,252,'45°',15,GREEN,55,22,700);
text(422,225,'60°',15,BLUE,55,22,700);
text(501,348,'P₃₀(√3/2, 1/2)',15,RED,145,22,700);
text(440,273,'P₄₅(√2/2, √2/2)',15,GREEN,145,22,700);
text(398,195,'P₆₀(1/2, √3/2)',15,BLUE,145,22,700);

text(526,318,'√3/3',14,RED,70,20,700);
text(526,216,'1',14,GREEN,70,20,700);
