  rect(m.x,m.y-10,10,10,'#98a2b3','#ffffff');
  text(m.x+118,m.y-92,m.deg,16,m.c,60,22,700);
  text(m.x+118,m.y-60,'sin = '+m.sin,13,m.c,110,20,700);
  text(m.x+118,m.y-38,'cos = '+m.cos,13,m.c,110,20,700);
  text(m.x+118,m.y-16,'tan = '+m.tan,13,m.c,110,20,700);
}

// Right: small right triangle
text(762,165,'小直角三角形',18,C,220,26,700);
const tx0=820, ty0=330, lx=820, ly=205, hx=980;
line(tx0,ty0,hx-tx0,0,'#98a2b3',3);
line(lx,ty0,0,ly-ty0,'#2563eb',3);
line(lx,ly,hx-lx,ty0-ly,'#172033',4);
rect(lx,ty0-12,12,12,'#98a2b3','#ffffff');
text(860,348,'邻边 cosθ',16,GREEN,150,24,700);
text(768,250,'对边\nsinθ',16,RED,70,46,700);
text(918,238,'斜边 = 1',16,C,100,24,700);
text(846,278,'θ',18,PURPLE,40,24,700);

// Exact value table
text(762,390,'精确值',18,C,160,26,700);
const tableX=[762,842,958,1080,1200];
const tableY=[424,462,500,538];
line(tableX[0],tableY[0]+40,570,0,'#cbd3df',2);
text(762,430,'角 θ',16,C,80,24,700);
text(845,430,'sin θ',16,C,100,24,700);
text(960,430,'cos θ',16,C,100,24,700);
text(1082,430,'tan θ',16,C,100,24,700);

const rows=[
  ['30°','1/2','√3/2','√3/3',RED],
  ['45°','√2/2','√2/2','1',GREEN],
  ['60°','√3/2','1/2','√3',BLUE],
