text(762,600,'随角度 θ 增大（30° → 45° → 60°）',18,C,560,26,700);
line(762,666,550,0,'#d4dae4',2);

text(762,638,'sin θ',16,RED,70,24,700);
text(835,638,'1/2',16,C,70,24,700);
line(898,650,58,0,RED,3);
text(970,638,'√2/2',16,C,70,24,700);
line(1040,650,58,0,RED,3);
